// =============================================================================
// Ingest Types
// =============================================================================

export interface IngestRecordResultResponse {
  index: number
  outcome: string
  reason?: string | null
  record_id?: string | null
  message_id?: string | null
  session_id?: string | null
  peer_id?: string | null
  derivation?: string | null
}

export interface IngestResponse {
  records: IngestRecordResultResponse[]
  receipt?: string | null
}

export interface IngestDeriveResponse {
  pending: number
  remaining: number
}

/** What happened to one ingested record. */
export interface IngestRecordResult {
  /** The record's position among the records passed to `ingest`. */
  index: number
  /** `created`, `duplicate` or `rejected`. */
  outcome: string
  /** Why a record was rejected, e.g. `content_conflict`. */
  reason?: string
  recordId?: string
  messageId?: string
  sessionId?: string
  peerId?: string
  /** `pending`, `queued` or `deferred`. */
  derivation?: string
}

/** One result per ingested record, in the order the records were passed. */
export interface IngestResult {
  records: IngestRecordResult[]
}

export interface IngestStatusResponse {
  records: { deferred: number; pending: number; queued: number }
  deferred_tokens: number
  people: number
  people_not_modeled: number
  sessions: number
  sessions_not_modeled: number
  sessions_being_deleted?: number
  suggestions?: IngestSuggestionCounts
}

export interface IngestAccountResponse {
  source: string
  source_instance: string
  id?: string | null
  display_name?: string | null
}

export interface IngestPersonResponse {
  peer_id: string
  display_name?: string | null
  accounts: IngestAccountResponse[]
  messages: number
  modeled: boolean
}

export interface IngestSessionResponse {
  session_id: string
  display_name?: string | null
  source: string
  source_instance: string
  messages: number
  modeled: boolean
}

/** What the workspace's imports produced, for review before deriving. */
export interface IngestStatus {
  /** Records by derivation state: `deferred` waits for `ingestDerive()`. */
  records: { deferred: number; pending: number; queued: number }
  /** Tokens in the messages of deferred records. */
  deferredTokens: number
  /** Peers created for imported accounts. */
  people: number
  /** Of those, peers with `observeMe` off: nothing is derived about them. */
  peopleNotModeled: number
  /** Sessions created for imported containers. */
  sessions: number
  /** Of those, sessions whose reasoning is off. */
  sessionsNotModeled: number
  /** Sessions a reset is still deleting; 0 once it has finished. */
  sessionsBeingDeleted: number
  /** Open suggested links by stage, and whether a refresh is under way. */
  suggestions: IngestSuggestionCounts
}

/** Open suggested links by stage, and whether a refresh is under way. */
export interface IngestSuggestionCounts {
  /** Made by the identity rules, by confidence. */
  rules: { high: number; low: number }
  refreshing: boolean
}

/** One source account mapped to a peer. */
export interface IngestAccount {
  source: string
  sourceInstance: string
  /** The account's ID in the source, when it has one. */
  id?: string
  displayName?: string
}

/** A peer created for imported accounts. */
export interface IngestPerson {
  peerId: string
  /** The first account's display name. */
  displayName?: string
  accounts: IngestAccount[]
  /** Records its accounts wrote. */
  messages: number
  /** False when `observeMe` is off: nothing is derived about it. */
  modeled: boolean
}

/** A session created for an imported container. */
export interface IngestSession {
  sessionId: string
  /** The container's display name in the source. */
  displayName?: string
  source: string
  sourceInstance: string
  /** Records in the session. */
  messages: number
  /** False when reasoning is off for the session: only summaries are made. */
  modeled: boolean
}

export interface IngestLinkResponse {
  peer_id: string
  merged: string[]
  accounts: IngestAccountResponse[]
}

export interface IngestUnlinkResponse {
  peer_id: string
  account: IngestAccountResponse
}

/** The kept person and every account that now maps to it. */
export interface IngestLinkResult {
  peerId: string
  /** The people linked into it. */
  merged: string[]
  accounts: IngestAccount[]
}

/** The person a linked account maps to again, from the next import on. */
export interface IngestUnlinkResult {
  peerId: string
  account: IngestAccount
}

export interface IngestSuggestionAccountResponse {
  source: string
  source_instance: string
  id?: string | null
  display_name?: string | null
  handle?: string | null
  peer_id?: string | null
  records: number
}

export interface IngestSuggestionResponse {
  id: string
  kind: string
  stage: 'rules'
  confidence: 'high' | 'low'
  score: number
  status: 'open' | 'accepted' | 'dismissed'
  linked: boolean
  accounts: IngestSuggestionAccountResponse[]
  evidence: { signal: string; level: string; detail: string }[]
  refreshed_at: string
}

/** One account of a suggestion, as it was when the suggestion was made. */
export interface IngestSuggestionAccount {
  source: string
  sourceInstance: string
  id?: string
  displayName?: string
  handle?: string
  /** The person it maps to now; undefined if it's gone. */
  peerId?: string
  /** Records it had written when the suggestion was made. */
  records: number
}

/**
 * Two accounts that look like one person, and why. Nothing is linked until
 * the suggestion is accepted.
 *
 * @experimental Ingest may change or stop working without notice.
 */
export interface IngestSuggestion {
  id: string
  kind: string
  /**
   * What made it: `rules`, the identity rules. With `confidence`, it names a
   * group of suggestions, such as `rules:high`.
   */
  stage: 'rules'
  /** `high`: evidence to accept at a glance. `low`: needs a closer look. */
  confidence: 'high' | 'low'
  score: number
  status: 'open' | 'accepted' | 'dismissed'
  /** The two accounts map to one person now, however it happened. */
  linked: boolean
  accounts: IngestSuggestionAccount[]
  evidence: { signal: string; level: string; detail: string }[]
  refreshedAt: string
}

/** The accepted suggestion, and the link it made (undefined when already one person). */
export interface IngestSuggestionAccepted {
  suggestion: IngestSuggestion
  link?: IngestLinkResult
}

/** How many deferred records were released for derivation. */
export interface IngestDeriveResult {
  /** Records released for derivation. */
  pending: number
  /** Records in the workspace still deferred. */
  remaining: number
}

// =============================================================================
// Pagination Types
// =============================================================================

export interface PageResponse<T> {
  items: T[]
  page: number
  size: number
  total: number
  pages: number
}
